package net.oxcodsnet.roadarchitect.fabric.events;

import net.minecraft.core.Registry;
import net.minecraft.core.registries.BuiltInRegistries;
import net.oxcodsnet.roadarchitect.worldgen.RoadFeatureRegistry;

/**
 * Registers the Road Architect feature type only.
 *
 * <p>Goosker 0.3.13 deliberately does NOT inject the road placed-features into
 * biome generation. Roads are applied after chunks are fully generated by the
 * loaded-chunk backfill queue. This keeps Road Architect entirely out of the
 * vanilla/Distant Horizons chunk-generation pipeline.</p>
 */
public final class RoadFeatureRegistryFabric {
    private RoadFeatureRegistryFabric() {}

    public static void register() {
        Registry.register(
                BuiltInRegistries.FEATURE,
                RoadFeatureRegistry.ROAD_FEATURE_KEY.location(),
                RoadFeatureRegistry.ROAD_FEATURE
        );
    }
}
